// Vidyabot Adaptive Learning Engine (n8n Automation Script)
const body = $input.item.json.body || {};
const action = body.action || 'ask_doubt';
const query = body.query || body.question || '';
const topic = body.topicTitle || 'Newton\'s Laws of Motion';
const lang = body.language || 'en';
const errorType = body.errorType || '';

let responseTitle = 'Adaptive Learning Guidance';
let responseText = '';
let steps = [];

if (action === 'simplify_error') {
  responseTitle = `3-Step Resolution for ${errorType || 'Concept'} Error`;
  if (lang === 'mr') {
    steps = [
      'पायरी १: मूळ संकल्पना समजून घ्या (उदा. जडत्व किंवा संवेग).',
      'पायरी २: योग्य सूत्र निवडा (F = ma किंवा p = mv) आणि दिलेल्या किमती मांडा.',
      'पायरी ३: एकके (SI Units: N, m/s², kg·m/s) नीट तपासून अंतिम उत्तर काढा.'
    ];
    responseText = `त्रुटी विश्लेषण: ${errorType} प्रकारची चूक सुधारण्यासाठी वरील ३ पायऱ्यांचे अनुसरण करा.`;
  } else if (lang === 'hi') {
    steps = [
      'चरण 1: मूल अवधारणा को स्पष्ट करें (जड़त्व या संवेग).',
      'चरण 2: सही सूत्र (F = ma या p = mv) का चयन करें और मान रखें।',
      'चरण 3: इकाइयों (SI Units) की दोबारा जांच करके अंतिम उत्तर प्राप्त करें।'
    ];
    responseText = `त्रुटि निवारण: ${errorType} को ठीक करने के लिए इन चरणों का पालन करें।`;
  } else {
    steps = [
      'Step 1: Identify the underlying physical principle (e.g. Inertia, Net Force, or Momentum).',
      'Step 2: State given values with standard SI units and select the matching formula (e.g. F = ma).',
      'Step 3: Perform unit verification and double-check arithmetic calculations.'
    ];
    responseText = `Error Diagnostics: Systematic breakdown for your ${errorType || 'misconception'} in ${topic}.`;
  }
} else {
  // Default Doubt Assistant
  if (lang === 'mr') {
    responseText = `विद्याबॉट (n8n द्वारे): ${topic} संदर्भातील तुमच्या शंकेचे उत्तर - गतीच्या नियमांनुसार प्रत्येक क्रियेला समान व विरुद्ध प्रतिक्रिया असते.`;
  } else if (lang === 'hi') {
    responseText = `विद्याबॉट (n8n संचालित): ${topic} के लिए आपका समाधान - गति के नियमों के अनुसार बल द्रव्यमान और त्वरण का गुणनफल है।`;
  } else {
    responseText = `Vidyabot (Powered by n8n Workflow): For "${query || topic}", remember that unbalanced forces cause change in momentum according to Newton's Laws. Keep practicing!`;
  }
}

return {
  status: 'success',
  provider: 'n8n Workflow Engine',
  workflow_id: 'vidyabot-ai-remediation',
  timestamp: new Date().toISOString(),
  reply: responseText,
  steps: steps,
  metadata: {
    topic: topic,
    action: action,
    language: lang
  }
};
